/**
 * `plans/index.json` – the list of the plans folder for static hosting (US5), generated by `tooling/plansIndex.ts`.
 * Shared by the generator (build/dev server) and the `StaticFilePlanRepository`.
 */
export interface PlansIndex {
  plans: PlansIndexPlan[];
  /** GPX files that no plan refers to */
  tracks: PlansIndexTrack[];
}

export interface PlansIndexPlan {
  /** File base name: `<id>.plan.json` */
  id: string;
  file: string;
  name: string;
  /** GPX file name; missing when the plan file can't be read */
  track?: string;
  summary?: { distanceKm: number; climbM: number; checkpoints: number };
  brevetKm?: number | null;
  /** Time limit of a custom brevet (US16) */
  customTimeLimitMin?: number | null;
  start?: { date: string; time: string };
  updatedAt?: string;
  /** Why the plan can't be opened (invalid file, missing track) */
  error?: string;
}

export interface PlansIndexTrack {
  file: string;
  /** Track name from the GPX, else the file name without extension */
  name: string;
}
